#!/usr/bin/env python3
"""Add 20 new tools for 2026-06-06 production batch.
Each tool is registered as `tool-custom` with self-contained customHtml + customScript
so generator.js can render them without per-tool type handlers.
"""
import json
import os

with open('tools.json', 'r', encoding='utf-8') as f:
    tools = json.load(f)

cat_map = {}
for c in tools:
    cat_map[c['category']] = c

def get_cat(name):
    if name not in cat_map:
        cat_map[name] = {'category': name, 'tools': []}
        tools.append(cat_map[name])
    return cat_map[name]

format_cat = get_cat('格式转换')
dev_cat = get_cat('开发工具')
life_cat = get_cat('生活实用')
encrypt_cat = get_cat('编码/加密')
text_cat = get_cat('文本工具')

